package com.tarapickle.identity.infrastructure.security;
import org.springframework.beans.factory.annotation.Value; import org.springframework.security.oauth2.jwt.*; import org.springframework.stereotype.Component; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import org.springframework.security.oauth2.jose.jws.MacAlgorithm;
@Component public class JwtTokenService { private final JwtEncoder encoder; private final String issuer,audience; private final Duration accessTtl,refreshTtl; private final SecureRandom random=new SecureRandom();
 public JwtTokenService(JwtEncoder encoder,@Value("${tarapickle.jwt.issuer}")String issuer,@Value("${tarapickle.jwt.audience}")String audience,@Value("${tarapickle.jwt.access-ttl}")Duration access,@Value("${tarapickle.jwt.refresh-ttl}")Duration refresh){this.encoder=encoder;this.issuer=issuer;this.audience=audience;accessTtl=access;refreshTtl=refresh;}
 public String access(UUID uid,UUID sid,Set<String> roles,Instant now){JwtClaimsSet claims=JwtClaimsSet.builder().issuer(issuer).audience(List.of(audience)).subject(uid.toString()).issuedAt(now).expiresAt(now.plus(accessTtl)).claim("sid",sid.toString()).claim("roles",roles).build(); return encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();}
 public String opaque(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} public Instant refreshExpiry(Instant now){return now.plus(refreshTtl);} public long accessSeconds(){return accessTtl.toSeconds();}
 public static String hash(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
